{"command":"cat <<'EOF' > /tmp/i3
#!/bin/sh
exit 0
EOF
chmod +x /tmp/i3
# Now we have full data. Let's parse to produce theme yaml.
# For each theme, we can produce colors mapping: each unique hex gets a name.
# But to preserve original output exactness (including case), we need to ensure when we apply our theme to same comprehensive conf, we produce same output.
# If we generate theme yaml where each distinct hex maps to a unique color name, and window_colors and bar_colors refer to those names, then applying will produce same hex values (same case) because our color definitions will be exactly those hex values.
# However we also need to handle special cases: some themes don't define certain fields, e.g., flat-gray doesn't define separator, active, urgent, urgent client.
# In our comprehensive test, placeholders remained, indicating theme didn't override.
# So we can detect which placeholders remained: if output equals input placeholder, then theme doesn't define that field.
# Let's write a script to generate theme yaml per theme based on comprehensive2.

cat <<'PY' > /tmp/gen_themes.py
import os, subprocess, pathlib
themes_input = [
    ("slate","Slate theme by Jody Ribton <jody@ribton.me>"),
    ("alphare","A beige theme by Alphare"),
    ("ubuntu","Ubuntu theme by lasers"),
    ("flat-gray","flat gray based theme"),
    ("purple","Purple theme by AAlakkad <http://aalakkad.me>"),
    ("archlinux","Archlinux theme by okraits <http://okraits.de>"),
    ("default","Default theme for i3wm <http://i3wm.org>"),
    ("debian","Debian theme by lasers"),
    ("oceanic-next","Theme by Valentin Weber inspired by voronianski (https://github.com/voronianski/oceanic-next-color-scheme)"),
    ("base16-tomorrow","Base16 Tomorrow, by Chris Kempson (http://chriskempson.com)"),
    ("okraits","A simple theme by okraits <http://okraits.de>"),
    ("icelines","icelines theme by mbfraga"),
    ("solarized","Solarized theme by lasers"),
    ("deep-purple","Inspired by the Purple and Default themes. By jcpst <http://jcpst.com>"),
    ("tomorrow-night-80s","Tomorrow Night 80s theme by jmfurlott <http://jmfurlott.com>"),
    ("seti","seti theme by Jody Ribton - based on the seti Atom theme at https://atom.io/themes/seti-ui"),
    ("lime","Lime theme by wei2912 <http://wei2912.github.io>, based on Archlinux theme by okraits <http://okraits.de>"),
    ("gruvbox","Made by freeware-preacher <https://github.com/freeware-preacher> to match gruvbox by morhetz <https://github.com/morhetz>"),
    ("mate","Theme for blending i3 into MATE"),
]

placeholders = {
    "separator": "#010101",
    "background": "#020202",
    "statusline": "#030303",
    "focused_ws": ("#040404","#050505","#060606","#060607"),
    "active_ws": ("#070707","#080808","#090909","#09090A"),
    "inactive_ws": ("#0A0A0A","#0B0B0B","#0C0C0C","#0C0C0D"),
    "urgent_ws": ("#0D0D0D","#0E0E0E","#0F0F0F","#0F0F10"),
    "focused": ("#101010","#111111","#121212","#131313"),
    "focused_inactive": ("#141414","#151515","#161616","#171717"),
    "unfocused": ("#181818","#191919","#1A1A1A","#1B1B1B"),
    "urgent": ("#1C1C1C","#1D1D1D","#1E1E1E","#1F1F1F"),
}

def run_theme(th):
    env = os.environ.copy()
    env["PATH"] = "/tmp:" + env.get("PATH","")
    subprocess.run(["/workspace/executable","-c","/tmp/comprehensive2.conf","-o","/tmp/out.conf",th], env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    txt = pathlib.Path("/tmp/out.conf").read_text()
    return txt

def parse_out(txt):
    # returns dict
    # bar colors
    bar = {}
    clients = {}
    for line in txt.splitlines():
        s = line.strip()
        if not s:
            continue
        if s.startswith("separator "):
            bar["separator"] = s.split()[1]
        elif s.startswith("background ") and "client" not in s:
            # bar background: first occurrence after bar
            # need to differentiate multiple bars: only one bar in comprehensive
            if "background" not in bar:
                bar["background"] = s.split()[1]
            else:
                # second? Actually comprehensive has only one bar
                pass
        elif s.startswith("statusline "):
            bar["statusline"] = s.split()[1]
        elif s.startswith("focused_workspace "):
            parts = s.split()[1:]
            # parts may be 3 or 4
            bar["focused_workspace"] = tuple(parts[:3])  # first 3
            if len(parts) >=4:
                bar["focused_workspace_child"] = parts[3]
        elif s.startswith("active_workspace "):
            parts = s.split()[1:]
            bar["active_workspace"] = tuple(parts[:3])
        elif s.startswith("inactive_workspace "):
            parts = s.split()[1:]
            bar["inactive_workspace"] = tuple(parts[:3])
        elif s.startswith("urgent_workspace "):
            parts = s.split()[1:]
            bar["urgent_workspace"] = tuple(parts[:3])
        elif s.startswith("client.focused "):
            # Could be focused_inactive also
            if "focused_inactive" in s:
                continue
            parts = s.split()[1:]
            clients["focused"] = tuple(parts)
        elif s.startswith("client.focused_inactive "):
            parts = s.split()[1:]
            clients["focused_inactive"] = tuple(parts)
        elif s.startswith("client.unfocused "):
            parts = s.split()[1:]
            clients["unfocused"] = tuple(parts)
        elif s.startswith("client.urgent "):
            parts = s.split()[1:]
            clients["urgent"] = tuple(parts)
        elif s.startswith("client.background "):
            parts = s.split()[1:]
            clients["background"] = tuple(parts)
    return bar, clients

# Now generate theme yaml structures
import yaml, json, sys
# We'll create a dict of themes with their definitions in terms of hex values that differ from placeholders
# For generating our own yaml, we want to map each hex that is not placeholder to a color name.
# Then window_colors and bar_colors will reference those names.

# Use placeholder detection
def is_placeholder_bar(key, value):
    if key in ["separator","background","statusline"]:
        return value == placeholders[key]
    elif key == "focused_workspace":
        return value == placeholders["focused_ws"][:3]
    elif key == "active_workspace":
        return value == placeholders["active_ws"][:3]
    elif key == "inactive_workspace":
        return value == placeholders["inactive_ws"][:3]
    elif key == "urgent_workspace":
        return value == placeholders["urgent_ws"][:3]
    return False

def is_placeholder_client(key, value):
    mapping = {
        "focused": "focused",
        "focused_inactive": "focused_inactive",
        "unfocused": "unfocused",
        "urgent": "urgent",
    }
    p = placeholders.get(mapping.get(key, ""), None)
    if p is None:
        return False
    return value == p

for th, desc in themes_input:
    txt = run_theme(th)
    bar, clients = parse_out(txt)
    print(f"Theme {th}:")
    print(" bar:", bar)
    print(" clients:", clients)
    # Determine which are overridden
    overridden_bar = {}
    for k,v in bar.items():
        if k.endswith("_child"):
            continue
        if k in ["separator","background","statusline"]:
            if v != placeholders[k]:
                overridden_bar[k] = v
        elif k == "focused_workspace":
            if v != placeholders["focused_ws"][:3]:
                overridden_bar[k] = v
        elif k == "active_workspace":
            if v != placeholders["active_ws"][:3]:
                overridden_bar[k] = v
        elif k == "inactive_workspace":
            if v != placeholders["inactive_ws"][:3]:
                overridden_bar[k] = v
        elif k == "urgent_workspace":
            if v != placeholders["urgent_ws"][:3]:
                overridden_bar[k] = v
    overridden_clients = {}
    for k,v in clients.items():
        if k == "background":
            # Always considered? In placeholder not defined, but if present and not placeholder, treat as overridden? Our comprehensive doesn't have placeholder for background client, it has #202020 input but we didn't set placeholder for it. So check against placeholder #202020? Actually comprehensive2 input has client.background #202020
            if v[0] != "#202020":
                overridden_clients[k] = v
            continue
        pl_key = k
        # placeholders mapping
        ph = placeholders.get(pl_key)
        if ph is None:
            continue
        if v != ph:
            overridden_clients[k] = v
    print("  overridden_bar:", overridden_bar)
    print("  overridden_clients:", overridden_clients)
    print()
PY
python3 /tmp/gen_themes.py 2>&1 | head -n 500
"}

