import pathlib, os, subprocess, ast

placeholders = {
    "separator": "#010101",
    "background": "#020202",
    "statusline": "#030303",
    "focused_ws": ("#040404","#050505","#060606","#060607"),
    "active_ws": ("#070707","#080808","#090909","#09090A"),
    "inactive_ws": ("#0A0A0A","#0B0B0B","#0C0C0C","#0C0C0D"),
    "urgent_ws": ("#0D0D0D","#0E0E0E","#0F0F0F","#0F0F10"),
    "focused": ("#101010","#111111","#121212","#131313"),
    "focused_inactive": ("#141414","#151515","#161616","#171717"),
    "unfocused": ("#181818","#191919","#1A1A1A","#1B1B1B"),
    "urgent": ("#1C1C1C","#1D1D1D","#1E1E1E","#1F1F1F"),
}

def run_theme(th):
    env = os.environ.copy()
    env["PATH"] = "/tmp:" + env.get("PATH","")
    subprocess.run(["/workspace/executable","-c","/tmp/comprehensive2.conf","-o","/tmp/out.conf",th], env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    txt = pathlib.Path("/tmp/out.conf").read_text()
    return txt

def parse_out(txt):
    bar = {}
    clients = {}
    for line in txt.splitlines():
        s = line.strip()
        if not s:
            continue
        if s.startswith("separator "):
            bar["separator"] = s.split()[1]
        elif s.startswith("background ") and "client" not in s:
            if "background" not in bar:
                bar["background"] = s.split()[1]
        elif s.startswith("statusline "):
            bar["statusline"] = s.split()[1]
        elif s.startswith("focused_workspace "):
            parts = s.split()[1:]
            bar["focused_workspace"] = tuple(parts[:3])
        elif s.startswith("active_workspace "):
            parts = s.split()[1:]
            bar["active_workspace"] = tuple(parts[:3])
        elif s.startswith("inactive_workspace "):
            parts = s.split()[1:]
            bar["inactive_workspace"] = tuple(parts[:3])
        elif s.startswith("urgent_workspace "):
            parts = s.split()[1:]
            bar["urgent_workspace"] = tuple(parts[:3])
        elif s.startswith("client.focused ") and "focused_inactive" not in s:
            parts = s.split()[1:]
            clients["focused"] = tuple(parts)
        elif s.startswith("client.focused_inactive "):
            parts = s.split()[1:]
            clients["focused_inactive"] = tuple(parts)
        elif s.startswith("client.unfocused "):
            parts = s.split()[1:]
            clients["unfocused"] = tuple(parts)
        elif s.startswith("client.urgent "):
            parts = s.split()[1:]
            clients["urgent"] = tuple(parts)
    return bar, clients

for th, desc in themes:
    txt = run_theme(th)
    bar, clients = parse_out(txt)
    # Determine overridden
    overridden_bar = {}
    for k,v in bar.items():
        if k in ["separator","background","statusline"]:
            if v != placeholders[k]:
                overridden_bar[k] = v
        elif k == "focused_workspace":
            if v != placeholders["focused_ws"][:3]:
                overridden_bar[k] = v
        elif k == "active_workspace":
            if v != placeholders["active_ws"][:3]:
                overridden_bar[k] = v
        elif k == "inactive_workspace":
            if v != placeholders["inactive_ws"][:3]:
                overridden_bar[k] = v
        elif k == "urgent_workspace":
            if v != placeholders["urgent_ws"][:3]:
                overridden_bar[k] = v
    overridden_clients = {}
    for k,v in clients.items():
        ph = placeholders.get(k)
        if ph and v != ph:
            overridden_clients[k] = v
    # Print Rust code
    print(f'Theme: {th}')
    print(f'  bar: {overridden_bar}')
    print(f'  clients: {overridden_clients}')
    # Generate Rust struct initialization
    # We'll produce a JSON-like for later
    import json
    print(json.dumps({"name": th, "desc": desc, "bar": overridden_bar, "clients": overridden_clients}))
    print()
