fn parse_config_for_themes(content: &str) -> (Vec<ParsedClient>, Vec<ParsedBar>) {
    let lines: Vec<&str> = content.lines().collect();
    let mut clients = Vec::new();
    let re_client = regex::Regex::new(r"(?i)^(\s*)client\.(focused_inactive|focused|unfocused|urgent)\s+(#[0-9a-fA-F]{6})\s+(#[0-9a-fA-F]{6})\s+(#[0-9a-fA-F]{6})\s+(#[0-9a-fA-F]{6})").unwrap();
    for (idx, line) in lines.iter().enumerate() {
        if let Some(caps) = re_client.captures(line) {
            let indent = caps.get(1).unwrap().as_str().to_string();
            let typ = caps.get(2).unwrap().as_str().to_lowercase();
            let c1 = caps.get(3).unwrap().as_str().to_string();
            let c2 = caps.get(4).unwrap().as_str().to_string();
            let c3 = caps.get(5).unwrap().as_str().to_string();
            let c4 = caps.get(6).unwrap().as_str().to_string();
            clients.push(ParsedClient { typ, colors: vec![c1,c2,c3,c4], line_idx: idx, indent });
        }
    }

    // Parse bar blocks
    let mut bars = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim_start();
        if trimmed.starts_with("bar") && trimmed.contains("{") {
            // Find bar start
            let bar_indent = line[..line.find("bar").unwrap_or(0)].to_string();
            let start_idx = i;
            // Count braces
            let mut brace_count = 0;
            for ch in line.chars() {
                if ch == '{' { brace_count += 1; }
                if ch == '}' { brace_count -= 1; }
            }
            let mut j = i+1;
            while j < lines.len() && brace_count > 0 {
                for ch in lines[j].chars() {
                    if ch == '{' { brace_count += 1; }
                    if ch == '}' { brace_count -= 1; }
                }
                j += 1;
            }
            let end_idx = if brace_count == 0 { j-1 } else { lines.len()-1 };
            // Now inside bar, find colors block
            let mut colors_start: Option<usize> = None;
            let mut colors_end: Option<usize> = None;
            let mut colors_indent: Option<String> = None;
            let mut inner_indent: Option<String> = None;
            let mut singles = Vec::new();
            let mut workspaces = Vec::new();
            // Search for colors {
            let mut k = start_idx+1;
            while k < end_idx {
                let l = lines[k];
                let t = l.trim_start();
                if t.starts_with("colors") && t.contains("{") {
                    colors_start = Some(k);
                    colors_indent = Some(l[..l.find("colors").unwrap_or(0)].to_string());
                    // count braces for colors
                    let mut bc = 0;
                    for ch in l.chars() {
                        if ch == '{' { bc += 1; }
                        if ch == '}' { bc -= 1; }
                    }
                    let mut kk = k+1;
                    while kk < end_idx && bc > 0 {
                        for ch in lines[kk].chars() {
                            if ch == '{' { bc += 1; }
                            if ch == '}' { bc -= 1; }
                        }
                        kk += 1;
                    }
                    colors_end = Some(if bc==0 { kk-1 } else { end_idx-1 });
                    // Now parse inside colors block
                    let inner_start = k+1;
                    let inner_end = colors_end.unwrap();
                    for idx2 in inner_start..inner_end {
                        let ll = lines[idx2];
                        let tt = ll.trim_start();
                        // singles
                        let re_single = regex::Regex::new(r"(?i)^\s*(separator|background|statusline)\s+(#[0-9a-fA-F]{6})").unwrap();
                        if let Some(caps) = re_single.captures(ll) {
                            let typ = caps.get(1).unwrap().as_str().to_lowercase();
                            let col = caps.get(2).unwrap().as_str().to_string();
                            let indent = ll[..ll.find(&typ).unwrap_or(0)].to_string();
                            if inner_indent.is_none() {
                                inner_indent = Some(indent.clone());
                            }
                            singles.push(ParsedBarSingle { typ, color: col, line_idx: idx2, indent });
                        }
                        // workspaces
                        let re_ws = regex::Regex::new(r"(?i)^\s*(focused_workspace|urgent_workspace|active_workspace|inactive_workspace)\s+(#[0-9a-fA-F]{6})\s+(#[0-9a-fA-F]{6})\s+(#[0-9a-fA-F]{6})(?:\s+(#[0-9a-fA-F]{6}))?").unwrap();
                        if let Some(caps) = re_ws.captures(ll) {
                            let typ = caps.get(1).unwrap().as_str().to_lowercase();
                            let c1 = caps.get(2).unwrap().as_str().to_string();
                            let c2 = caps.get(3).unwrap().as_str().to_string();
                            let c3 = caps.get(4).unwrap().as_str().to_string();
                            let indent = ll[..ll.find(&typ).unwrap_or(0)].to_string();
                            if inner_indent.is_none() {
                                inner_indent = Some(indent.clone());
                            }
                            let mut colors = vec![c1,c2,c3];
                            if let Some(m) = caps.get(5) {
                                colors.push(m.as_str().to_string());
                            }
                            workspaces.push(ParsedBarWorkspace { typ, colors, line_idx: idx2, indent, original_line: ll.to_string() });
                        }
                    }
                    break;
                }
                k += 1;
            }

            bars.push(ParsedBar {
                start_idx,
                end_idx,
                indent: bar_indent,
                colors_start,
                colors_end,
                colors_indent,
                inner_indent,
                singles,
                workspaces,
            });
            i = end_idx;
        }
        i += 1;
    }

    (clients, bars)
}

fn generate_theme_from_config(config_path: &Path) -> Result<String, String> {
    let content = fs::read_to_string(config_path).map_err(|e| format!("Could not open theme: {} - {} (os error {})", config_path.display(), e, e.raw_os_error().unwrap_or(0)))?;
    // Actually for to-theme, error should panic? But we will return error string for panic case
    // For to-theme, we need to handle file not found as panic with specific message from theme.rs
    // We'll let caller handle panic.

    let (clients, bars) = parse_config_for_themes(&content);

    // Collect unique hex in order of appearance
    let mut ordered_hex: Vec<String> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();

    // From clients: in order of appearance (already)
    for c in &clients {
        for col in &c.colors {
            let up = col.to_uppercase();
            let key = up.clone();
            if !seen.contains(&key) {
                seen.insert(key);
                ordered_hex.push(col.clone());
            }
        }
    }

    // From bars: singles and workspaces (but only those we care for to-theme: background, statusline, separator, focused_workspace, urgent_workspace)
    // For to-theme, original only includes focused and urgent, not active/inactive. Let's replicate.
    for bar in &bars {
        for s in &bar.singles {
            // include only background, statusline, separator
            if ["background","statusline","separator"].contains(&s.typ.as_str()) {
                let col = &s.color;
                let up = col.to_uppercase();
                if !seen.contains(&up) {
                    seen.insert(up);
                    ordered_hex.push(col.clone());
                }
            }
        }
        for ws in &bar.workspaces {
            if ["focused_workspace","urgent_workspace"].contains(&ws.typ.as_str()) {
                for col in &ws.colors {
                    if col.len() < 3 { continue; }
                    // only first 3
                    // ws.colors may have 4, but we only take first 3
                    // We'll iterate first 3
                }
                for col in ws.colors.iter().take(3) {
                    let up = col.to_uppercase();
                    if !seen.contains(&up) {
                        seen.insert(up);
                        ordered_hex.push(col.clone());
                    }
                }
            }
        }
    }

    // Now map each hex to nearest name with dedup handling
    let mut name_for_hex: HashMap<String, String> = HashMap::new(); // uppercase hex -> name
    let mut used_names: HashMap<String, String> = HashMap::new(); // base name -> hex (first occurrence)
    let mut name_counts: HashMap<String, usize> = HashMap::new();
    let mut ordered_colors: Vec<(String,String)> = Vec::new(); // (name, hex uppercase)

    for hex in ordered_hex {
        let up_hex = hex.to_uppercase();
        // Actually to-theme uppercases hex in output
        let upper_hex = up_hex.clone();
        if name_for_hex.contains_key(&upper_hex) {
            continue;
        }
        let base = nearest_color_name(&hex);
        let mut final_name = base.clone();
        if let Some(existing_hex) = used_names.get(&base) {
            if existing_hex != &upper_hex {
                // need suffix
                let mut idx = 1;
                loop {
                    let candidate = format!("{}-{}", base, idx);
                    if !used_names.contains_key(&candidate) {
                        final_name = candidate;
                        break;
                    }
                    idx += 1;
                }
            }
        }
        used_names.insert(final_name.clone(), upper_hex.clone());
        used_names.insert(base.clone(), upper_hex.clone()); // also track base?
        // Actually need to track used names, not base. Simpler: track final_name used.
        // We'll use a set of used final names
        // But we already use used_names as map name->hex, we should check final_name existence
        // Let's implement correctly below with separate structures

        // For now, push
        name_for_hex.insert(upper_hex.clone(), final_name.clone());
        ordered_colors.push((final_name, upper_hex));
    }

    // Re-implement correctly with proper dedup
    // Reset and do again more accurately
    let mut seen_hex: HashSet<String> = HashSet::new();
    let mut used_name_to_hex: HashMap<String, String> = HashMap::new();
    let mut name_for_hex2: HashMap<String, String> = HashMap::new();
    let mut ordered2: Vec<(String,String)> = Vec::new();
    //Need original ordered list of unique hex in appearance order
    // We have ordered_hex already but it was collected with original case, let's re-collect unique in order preserving first appearance
    // Actually we need to recompute ordered_unique from scratch in appearance order
    // Let's re-parse appearance order: clients first, then bars
    let mut appearance: Vec<String> = Vec::new();
    let mut seen_appear: HashSet<String> = HashSet::new();
    for c in &clients {
        for col in &c.colors {
            let up = col.to_uppercase();
            if !seen_appear.contains(&up) {
                seen_appear.insert(up.clone());
                appearance.push(col.clone());
            }
        }
    }
    for bar in &bars {
        for s in &bar.singles {
            if ["background","statusline","separator"].contains(&s.typ.as_str()) {
                let up = s.color.to_uppercase();
                if !seen_appear.contains(&up) {
                    seen_appear.insert(up.clone());
                    appearance.push(s.color.clone());
                }
            }
        }
        for ws in &bar.workspaces {
            if ["focused_workspace","urgent_workspace"].contains(&ws.typ.as_str()) {
                for col in ws.colors.iter().take(3) {
                    let up = col.to_uppercase();
                    if !seen_appear.contains(&up) {
                        seen_appear.insert(up.clone());
                        appearance.push(col.clone());
                    }
                }
            }
        }
    }

    for hex in appearance {
        let up = hex.to_uppercase();
        if name_for_hex2.contains_key(&up) {
            continue;
        }
        let base = nearest_color_name(&hex);
        let mut candidate = base.clone();
        let mut suffix = 0;
        loop {
            if let Some(existing_hex) = used_name_to_hex.get(&candidate) {
                if existing_hex == &up {
                    break;
                } else {
                    suffix += 1;
                    candidate = format!("{}-{}", base, suffix);
                    continue;
                }
            } else {
                break;
            }
        }
        used_name_to_hex.insert(candidate.clone(), up.clone());
        name_for_hex2.insert(up.clone(), candidate.clone());
        ordered2.push((candidate, up));
    }

    // Now generate YAML
    let mut yaml = String::new();
    yaml.push_str("---\n");
    yaml.push_str("meta:\n");
    yaml.push_str("  description: AUTOMATICALLY GENERATED THEME\n");
    yaml.push_str("colors:\n");
    for (name, hex) in &ordered2 {
        yaml.push_str(&format!("  {}: \"{}\"\n", name, hex));
    }
    yaml.push_str("window_colors:\n");
    // Group clients by type
    let mut clients_by_type: HashMap<String, Vec<&ParsedClient>> = HashMap::new();
    for c in &clients {
        clients_by_type.entry(c.typ.clone()).or_default().push(c);
    }
    for typ in ["focused","focused_inactive","unfocused","urgent"] {
        if let Some(list) = clients_by_type.get(typ) {
            if let Some(last) = list.last() {
                yaml.push_str(&format!("  {}:\n", typ));
                let fields = ["border","background","text","indicator"];
                for (i, field) in fields.iter().enumerate() {
                    if i < last.colors.len() {
                        let hex = last.colors[i].to_uppercase();
                        if let Some(name) = name_for_hex2.get(&hex) {
                            yaml.push_str(&format!("    {}: {}\n", field, name));
                        }
                    }
                }
            }
        }
    }
    yaml.push_str("bar_colors:\n");
    // For bar, we need to consider last bar's colors? Original uses last bar for to-theme? We observed multiple bars uses last bar. So we should take last bar if exists
    if let Some(last_bar) = bars.last() {
        for single_type in ["background","statusline","separator"] {
            // find last occurrence of this type in last_bar
            if let Some(s) = last_bar.singles.iter().filter(|x| x.typ == single_type).last() {
                let up = s.color.to_uppercase();
                if let Some(name) = name_for_hex2.get(&up) {
                    yaml.push_str(&format!("  {}: {}\n", single_type, name));
                }
            }
        }
        for ws_type in ["focused_workspace","urgent_workspace"] {
            if let Some(ws) = last_bar.workspaces.iter().filter(|x| x.typ == ws_type).last() {
                yaml.push_str(&format!("  {}:\n", ws_type));
                let fields = ["border","background","text"];
                for (i, field) in fields.iter().enumerate() {
                    if i < ws.colors.len() {
                        let up = ws.colors[i].to_uppercase();
                        if let Some(name) = name_for_hex2.get(&up) {
                            yaml.push_str(&format!("    {}: {}\n", field, name));
                        }
                    }
                }
            }
        }
    }

    Ok(yaml)
}

fn apply_theme_to_config(config_path: &Path, theme: &ResolvedTheme, output_path: Option<&Path>, save: bool, validate: bool) -> Result<String, String> {
    // Read config
    let content = fs::read_to_string(config_path).map_err(|e| {
        // Original panicked with writer.rs:24 unwrap, but we will print similar panic? For matching behavior, we should panic with same message?
        // The original panic message included "called `Result::unwrap()` on an `Err` value: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }"
        // For simplicity, we will panic via unwrap to produce same exit code 101 and message.
        // We'll use std::panic::panic with message? But we can just cause panic by unwrap
        // However for this function we return error and caller will panic if needed.
        format!("Config file not found: {} - {} (os error {})", config_path.display(), e, e.raw_os_error().unwrap_or(0))
    })?;

    // Parse config for bars and clients
    let (clients, bars) = parse_config_for_themes(&content);
    let lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
    let mut new_lines = lines.clone();

    // For clients: replace
    // Build map of theme clients: type -> Vec of hex (resolved)
    // For each ParsedClient, if theme has that type, replace
    for pc in clients {
        if let Some(theme_colors) = theme.clients.get(&pc.typ) {
            // theme_colors is Vec of hex, may have empty strings for undefined fields
            // pc.colors is Vec of 4
            let mut new_colors = pc.colors.clone();
            for i in 0..theme_colors.len().min(4) {
                if !theme_colors[i].is_empty() {
                    new_colors[i] = theme_colors[i].clone();
                }
            }
            // Reconstruct line preserving indent and original formatting?
            // Original line: indent + "client." + type + " " + colors joined by space
            let new_line = format!("{}client.{} {}", pc.indent, pc.typ, new_colors.join(" "));
            new_lines[pc.line_idx] = new_line;
        }
    }

    // Check for client types in theme that are not present in config: add at end
    let existing_client_types: HashSet<String> = parse_config_for_themes(&content).0.iter().map(|c| c.typ.clone()).collect();
    let mut added_clients = Vec::new();
    for (typ, theme_colors) in &theme.clients {
        if !existing_client_types.contains(typ) {
            // If any of its colors empty, skip? For builtin themes, they have all 4 defined
            // But if partial, we should still add with whatever defined? Original behavior: if theme defines only border, what does it do for non-existing client? It adds client line with border from theme and black for others? Let's not worry: we will add only if all 4 defined or at least one? In earlier tests, adding worked for themes with full definitions.
            // For simplicity, if theme_colors has at least one non-empty, we add line with its colors, using empty as placeholder? Better to require all 4 non-empty.
            if theme_colors.iter().all(|c| !c.is_empty()) {
                added_clients.push(format!("client.{} {}", typ, theme_colors.join(" ")));
            }
        }
    }

    // For bars: iterate over each bar
    // We need to modify new_lines for bar sections
    // For each bar, we need to handle its colors block
    // We'll process bars in reverse order to not mess up indices when inserting
    let mut bars_sorted = bars.clone();
    bars_sorted.sort_by(|a,b| b.start_idx.cmp(&a.start_idx));

    for bar in bars_sorted {
        // Determine if colors block exists
        if let (Some(cs), Some(ce)) = (bar.colors_start, bar.colors_end) {
            // Existing colors block: we have singles and workspaces with line indices
            // For each theme bar entry
            for (typ, theme_cols) in &theme.bar {
                if ["background","statusline","separator"].contains(&typ.as_str()) {
                    // single
                    // Find existing entry of this type in bar
                    let existing = bar.singles.iter().find(|s| s.typ == *typ);
                    if let Some(ex) = existing {
                        if let Some(hex) = theme_cols.get(0) {
                            if !hex.is_empty() {
                                // Replace line
                                let new_line = format!("{}{} {}", ex.indent, typ, hex);
                                new_lines[ex.line_idx] = new_line;
                            }
                        }
                    } else {
                        // Add new entry inside colors block, before its closing }
                        // Insert before ce (which is line with })
                        // Use inner_indent if available else default 4 spaces
                        let indent = bar.inner_indent.clone().unwrap_or_else(|| "    ".to_string());
                        if let Some(hex) = theme_cols.get(0) {
                            if !hex.is_empty() {
                                let new_entry = format!("{}{} {}", indent, typ, hex);
                                // Insert at position ce (before closing)
                                new_lines.insert(ce, new_entry);
                                // Need to adjust subsequent bar indices? Since we process reverse, it's okay for this iteration, but for earlier bars we already sorted reverse, so insertion won't affect earlier processed bars that are before? Actually inserting will shift indices for earlier bars (with smaller start_idx). But we process from last to first, so earlier bars indices are before ce, so inserting at ce (which is after their end) won't affect them? Wait ce is within bar, and bar.start_idx < ce < bar.end_idx. For earlier bars (with smaller start_idx), their end_idx is < current bar's start_idx? Actually since we sorted descending by start_idx, current bar is last, its indices are highest. Earlier bars have lower indices, so insertion at ce (high index) won't affect earlier bars indices (since they are before). So okay.
                            }
                        }
                    }
                } else {
                    // workspace
                    let existing = bar.workspaces.iter().find(|w| w.typ == *typ);
                    if let Some(ex) = existing {
                        // Replace
                        // ex.colors has 3 or 4
                        let mut new_cols = ex.colors.clone();
                        // Ensure new_cols has at least 3
                        while new_cols.len() < 3 {
                            new_cols.push("".to_string());
                        }
                        for i in 0..theme_cols.len().min(3) {
                            if !theme_cols[i].is_empty() {
                                if i < new_cols.len() {
                                    new_cols[i] = theme_cols[i].clone();
                                } else {
                                    new_cols.push(theme_cols[i].clone());
                                }
                            }
                        }
                        // Preserve 4th if existed in original and theme doesn't provide 4th? Original theme never provides 4th, so preserve
                        // If original had 4, new_cols will have 4 (preserved from ex.colors[3] if not overwritten)
                        // Actually we already kept original 4th in new_cols if ex had 4 and we didn't overwrite 4th (since theme only 3)
                        // For formatting: if new_cols has 4, output without trailing space, else with trailing space
                        let output = if new_cols.len() >= 4 {
                            format!("{}{} {}", ex.indent, typ, new_cols.join(" "))
                        } else {
                            // 3 entries + trailing space
                            format!("{}{} {} ", ex.indent, typ, new_cols[..3].join(" "))
                        };
                        new_lines[ex.line_idx] = output;
                    } else {
                        // Add new
                        let indent = bar.inner_indent.clone().unwrap_or_else(|| "    ".to_string());
                        // Only add if theme defines all 3?
                        if theme_cols.len() >= 3 && theme_cols[0..3].iter().all(|c| !c.is_empty()) {
                            let new_entry = format!("{}{} {} ", indent, typ, theme_cols[0..3].join(" "));
                            new_lines.insert(ce, new_entry);
                        }
                    }
                }
            }
        } else {
            // No colors block: need to create one
            // Determine where to insert: before bar's closing }
            // bar.end_idx is line with }
            // We need to insert colors block with theme's bar colors
            // For simplicity, use default indent of 2 for colors and 4 for inner
            // But we should try to preserve bar's inner indent? When no colors block, original used 2 spaces for "  colors {" and 4 for inner, regardless of bar's indentation? In earlier tests, for empty bar {}, it used 2 and 4 even though bar had no inner indent. For bar with status_command indented 8, it used 2 and 4 for colors block, not preserving status_command indent. So we will use 2 and 4.
            // However for bar that had colors block with custom indent, we already handled preserving indent.
            // For no colors block case, we need to create colors block
            let colors_indent = "  ".to_string();
            let inner_indent = "    ".to_string();
            let mut colors_block = Vec::new();
            colors_block.push(format!("{}colors {{", colors_indent));
            // Add entries for each theme bar type
            for (typ, cols) in &theme.bar {
                if ["background","statusline","separator"].contains(&typ.as_str()) {
                    if let Some(hex) = cols.get(0) {
                        if !hex.is_empty() {
                            colors_block.push(format!("{}{} {}", inner_indent, typ, hex));
                        }
                    }
                } else {
                    if cols.len() >= 3 && cols[0..3].iter().all(|c| !c.is_empty()) {
                        colors_block.push(format!("{}{} {} ", inner_indent, typ, cols[0..3].join(" ")));
                    }
                }
            }
            colors_block.push(format!("{}}}", colors_indent));
            // Insert before bar.end_idx
            let insert_pos = bar.end_idx;
            // Insert in reverse to keep order
            for (offset, line) in colors_block.iter().rev().enumerate() {
                new_lines.insert(insert_pos, line.clone());
            }
        }
    }

    // Add new client lines at end if any
    let mut final_content = new_lines.join("\n");
    if !added_clients.is_empty() {
        // Ensure file ends with newline?
        if !final_content.ends_with('\n') {
            final_content.push('\n');
        }
        for ac in added_clients {
            final_content.push_str(&ac);
            final_content.push('\n');
        }
    } else {
        // Preserve original trailing newline? Original config may or may not have trailing newline. Our join loses final newline if original had none? Let's check: lines() strips final empty? We'll ensure we add newline at end if original ended with newline.
        // Simpler: if original content ends with newline, ensure final ends with newline
        if content.ends_with('\n') && !final_content.ends_with('\n') {
            final_content.push('\n');
        }
    }

    Ok(final_content)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    // Manual arg parsing to match original behavior
    let mut config_path: Option<String> = None;
    let mut output_path: Option<String> = None;
    let mut to_theme_path: Option<String> = None;
    let mut theme_arg: Option<String> = None;
    let mut list_all = false;
    let mut reload = false;
    let mut save = false;
    let mut help = false;
    let mut version = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                help = true;
                i += 1;
            }
            "-V" | "--version" => {
                version = true;
                i += 1;
            }
            "-l" | "--list-all" => {
                list_all = true;
                i += 1;
            }
            "-r" | "--reload" => {
                reload = true;
                i += 1;
            }
            "-s" | "--save" => {
                save = true;
                i += 1;
            }
            "-c" | "--config" => {
                if i+1 < args.len() {
                    config_path = Some(args[i+1].clone());
                    i += 2;
                } else {
                    eprintln!("error: option {} requires an argument", arg);
                    process::exit(1);
                }
            }
            "-o" | "--output" => {
