use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

mod embedded;

use embedded::builtin_themes;

#[derive(Debug, Clone)]
struct ResolvedTheme {
    name: String,
    description: String,
    bar: HashMap<String, Vec<String>>,
    clients: HashMap<String, Vec<String>>,
}

fn print_help() {
    println!("i3-style 1.0");
    println!("Make your i3 config a bit more stylish");
    println!();
    println!("USAGE:");
    println!("    executable [FLAGS] [OPTIONS] [theme]");
    println!();
