fn hex_to_rgb(hex: &str) -> Option<(u8,u8,u8)> {
    let hex = hex.trim_start_matches('#');
    if hex.len() != 6 {
        return None;
    }
    let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
    let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
    let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
    Some((r,g,b))
}

fn nearest_color_name(hex: &str) -> String {
    if let Some((r,g,b)) = hex_to_rgb(hex) {
        let mut best_name = "black";
        let mut best_dist = i32::MAX;
        for (name, (cr,cg,cb)) in CSS_COLORS {
            let dr = r as i32 - *cr as i32;
            let dg = g as i32 - *cg as i32;
            let db = b as i32 - *cb as i32;
            let dist = dr*dr + dg*dg + db*db;
            if dist < best_dist {
                best_dist = dist;
                best_name = name;
            }
        }
        best_name.to_string()
    } else {
        "black".to_string()
    }
}

#[derive(Debug, Clone)]
struct ParsedClient {
    typ: String,
    colors: Vec<String>,
    line_idx: usize,
    indent: String,
}

#[derive(Debug, Clone)]
struct ParsedBarWorkspace {
    typ: String,
    colors: Vec<String>,
    line_idx: usize,
    indent: String,
}

#[derive(Debug, Clone)]
struct ParsedBarSingle {
    typ: String,
    color: String,
    line_idx: usize,
    indent: String,
}

#[derive(Debug, Clone)]
struct ParsedBar {
    start_idx: usize,
    end_idx: usize,
    colors_start: Option<usize>,
    colors_end: Option<usize>,
    inner_indent: Option<String>,
    singles: Vec<ParsedBarSingle>,
    workspaces: Vec<ParsedBarWorkspace>,
}

fn parse_config_for_themes(content: &str) -> (Vec<ParsedClient>, Vec<ParsedBar>) {
    let lines: Vec<&str> = content.lines().collect();
    let mut clients = Vec::new();
    let re_client = regex::Regex::new(r"(?i)^(\s*)client\.(focused_inactive|focused|unfocused|urgent)\s+(#[0-9a-fA-F]{6})\s+(#[0-9a-fA-F]{6})\s+(#[0-9a-fA-F]{6})\s+(#[0-9a-fA-F]{6})").unwrap();
    for (idx, line) in lines.iter().enumerate() {
        if let Some(caps) = re_client.captures(line) {
            let indent = caps.get(1).unwrap().as_str().to_string();
            let typ = caps.get(2).unwrap().as_str().to_lowercase();
            let c1 = caps.get(3).unwrap().as_str().to_string();
            let c2 = caps.get(4).unwrap().as_str().to_string();
            let c3 = caps.get(5).unwrap().as_str().to_string();
            let c4 = caps.get(6).unwrap().as_str().to_string();
            clients.push(ParsedClient { typ, colors: vec![c1,c2,c3,c4], line_idx: idx, indent });
        }
    }

    let mut bars = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim_start();
        if trimmed.starts_with("bar") && trimmed.contains("{") {
            let start_idx = i;
            let mut brace_count = 0;
            for ch in line.chars() {
                if ch == '{' { brace_count += 1; }
                if ch == '}' { brace_count -= 1; }
            }
            let mut j = i+1;
            while j < lines.len() && brace_count > 0 {
                for ch in lines[j].chars() {
                    if ch == '{' { brace_count += 1; }
                    if ch == '}' { brace_count -= 1; }
                }
                j += 1;
            }
            let end_idx = if brace_count == 0 { j-1 } else { lines.len()-1 };
            let mut colors_start: Option<usize> = None;
            let mut colors_end: Option<usize> = None;
            let mut inner_indent: Option<String> = None;
            let mut singles = Vec::new();
            let mut workspaces = Vec::new();
            let mut k = start_idx+1;
            while k < end_idx {
                let l = lines[k];
                let t = l.trim_start();
                if t.starts_with("colors") && t.contains("{") {
                    colors_start = Some(k);
                    let mut bc = 0;
                    for ch in l.chars() {
                        if ch == '{' { bc += 1; }
                        if ch == '}' { bc -= 1; }
                    }
                    let mut kk = k+1;
                    while kk < end_idx && bc > 0 {
                        for ch in lines[kk].chars() {
                            if ch == '{' { bc += 1; }
                            if ch == '}' { bc -= 1; }
                        }
                        kk += 1;
                    }
                    colors_end = Some(if bc==0 { kk-1 } else { end_idx-1 });
                    let inner_start = k+1;
                    let inner_end = colors_end.unwrap();
                    for idx2 in inner_start..inner_end {
                        let ll = lines[idx2];
                        let re_single = regex::Regex::new(r"(?i)^\s*(separator|background|statusline)\s+(#[0-9a-fA-F]{6})").unwrap();
                        if let Some(caps) = re_single.captures(ll) {
                            let typ = caps.get(1).unwrap().as_str().to_lowercase();
                            let col = caps.get(2).unwrap().as_str().to_string();
                            let indent = ll[..ll.to_lowercase().find(&typ).unwrap_or(0)].to_string();
                            if inner_indent.is_none() {
                                inner_indent = Some(indent.clone());
                            }
                            singles.push(ParsedBarSingle { typ, color: col, line_idx: idx2, indent });
                        }
                        let re_ws = regex::Regex::new(r"(?i)^\s*(focused_workspace|urgent_workspace|active_workspace|inactive_workspace)\s+(#[0-9a-fA-F]{6})\s+(#[0-9a-fA-F]{6})\s+(#[0-9a-fA-F]{6})(?:\s+(#[0-9a-fA-F]{6}))?").unwrap();
                        if let Some(caps) = re_ws.captures(ll) {
                            let typ = caps.get(1).unwrap().as_str().to_lowercase();
                            let c1 = caps.get(2).unwrap().as_str().to_string();
                            let c2 = caps.get(3).unwrap().as_str().to_string();
                            let c3 = caps.get(4).unwrap().as_str().to_string();
                            let indent = ll[..ll.to_lowercase().find(&typ).unwrap_or(0)].to_string();
                            if inner_indent.is_none() {
                                inner_indent = Some(indent.clone());
                            }
                            let mut colors = vec![c1,c2,c3];
                            if let Some(m) = caps.get(5) {
                                colors.push(m.as_str().to_string());
                            }
                            workspaces.push(ParsedBarWorkspace { typ, colors, line_idx: idx2, indent });
                        }
                    }
                    break;
                }
                k += 1;
            }
            bars.push(ParsedBar {
                start_idx,
                end_idx,
                colors_start,
                colors_end,
                inner_indent,
                singles,
                workspaces,
            });
            i = end_idx;
        }
        i += 1;
    }
    (clients, bars)
}

fn generate_theme_from_config(config_path: &Path) -> Result<String, String> {
    let content = fs::read_to_string(config_path).map_err(|e| format!("{} (os error {})", e, e.raw_os_error().unwrap_or(0)))?;

    let (clients, bars) = parse_config_for_themes(&content);

    #[derive(Debug)]
    struct ColorEvent {
        line_idx: usize,
        col_idx: usize,
        hex: String,
    }
    let mut events: Vec<ColorEvent> = Vec::new();
    for c in &clients {
        for (ci, col) in c.colors.iter().enumerate() {
            events.push(ColorEvent { line_idx: c.line_idx, col_idx: ci, hex: col.clone() });
        }
    }
    for bar in &bars {
        for s in &bar.singles {
            events.push(ColorEvent { line_idx: s.line_idx, col_idx: 0, hex: s.color.clone() });
        }
        for ws in &bar.workspaces {
            if ws.typ == "active_workspace" {
                continue;
            }
            for (ci, col) in ws.colors.iter().take(3).enumerate() {
                events.push(ColorEvent { line_idx: ws.line_idx, col_idx: ci, hex: col.clone() });
            }
        }
    }
    events.sort_by(|a,b| a.line_idx.cmp(&b.line_idx).then(a.col_idx.cmp(&b.col_idx)));

    let mut appearance: Vec<String> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();
    for ev in events {
        let up = ev.hex.to_uppercase();
        if !seen.contains(&up) {
            seen.insert(up.clone());
            appearance.push(ev.hex.clone());
        }
    }

    if appearance.is_empty() {
        return Ok("---\nmeta:\n  description: AUTOMATICALLY GENERATED THEME\ncolors: {}\nwindow_colors: {}\nbar_colors: {}\n".to_string());
    }

    let mut used_name_to_hex: HashMap<String, String> = HashMap::new();
    let mut name_for_hex: HashMap<String, String> = HashMap::new();
    let mut ordered: Vec<(String,String)> = Vec::new();

    for hex in appearance {
        let up = hex.to_uppercase();
        if name_for_hex.contains_key(&up) {
            continue;
        }
        let base = nearest_color_name(&hex);
        let mut candidate = base.clone();
        let mut suffix = 0;
        loop {
            if let Some(existing_hex) = used_name_to_hex.get(&candidate) {
                if existing_hex == &up {
                    break;
                } else {
                    suffix += 1;
                    candidate = format!("{}-{}", base, suffix);
                    continue;
                }
            } else {
                break;
            }
        }
        used_name_to_hex.insert(candidate.clone(), up.clone());
        name_for_hex.insert(up.clone(), candidate.clone());
        ordered.push((candidate, up));
    }

    let mut final_yaml = String::new();
    final_yaml.push_str("---\n");
    final_yaml.push_str("meta:\n");
    final_yaml.push_str("  description: AUTOMATICALLY GENERATED THEME\n");
    final_yaml.push_str("colors:\n");
    for (name, hex) in &ordered {
        final_yaml.push_str(&format!("  {}: \"{}\"\n", name, hex));
    }

    let mut clients_by_type: HashMap<String, Vec<&ParsedClient>> = HashMap::new();
    for c in &clients {
        clients_by_type.entry(c.typ.clone()).or_default().push(c);
    }
    let has_any_window = !clients.is_empty();
    if !has_any_window {
        final_yaml.push_str("window_colors: {}\n");
    } else {
        final_yaml.push_str("window_colors:\n");
        for typ in ["focused","focused_inactive","unfocused","urgent"] {
            if let Some(list) = clients_by_type.get(typ) {
                if let Some(last) = list.last() {
                    final_yaml.push_str(&format!("  {}:\n", typ));
                    let fields = ["border","background","text","indicator"];
                    for (i, field) in fields.iter().enumerate() {
                        if i < last.colors.len() {
                            let up = last.colors[i].to_uppercase();
                            if let Some(name) = name_for_hex.get(&up) {
                                final_yaml.push_str(&format!("    {}: {}\n", field, name));
                            }
                        }
                    }
                }
            }
        }
    }

    let has_any_bar = if let Some(last_bar) = bars.last() {
        !last_bar.singles.is_empty() || last_bar.workspaces.iter().any(|w| ["focused_workspace","urgent_workspace","separator","background","statusline"].contains(&w.typ.as_str()))
    } else {
        false
    };
    if !has_any_bar {
        final_yaml.push_str("bar_colors: {}\n");
    } else {
        final_yaml.push_str("bar_colors:\n");
        if let Some(last_bar) = bars.last() {
            for single_type in ["background","statusline","separator"] {
                if let Some(s) = last_bar.singles.iter().filter(|x| x.typ == single_type).last() {
                    let up = s.color.to_uppercase();
                    if let Some(name) = name_for_hex.get(&up) {
                        final_yaml.push_str(&format!("  {}: {}\n", single_type, name));
                    }
                }
            }
            for ws_type in ["focused_workspace","urgent_workspace"] {
                if let Some(ws) = last_bar.workspaces.iter().filter(|x| x.typ == ws_type).last() {
                    final_yaml.push_str(&format!("  {}:\n", ws_type));
                    let fields = ["border","background","text"];
                    for (i, field) in fields.iter().enumerate() {
                        if i < ws.colors.len() {
                            let up = ws.colors[i].to_uppercase();
                            if let Some(name) = name_for_hex.get(&up) {
                                final_yaml.push_str(&format!("    {}: {}\n", field, name));
                            }
                        }
                    }
                }
            }
        }
    }

    Ok(final_yaml)
}

fn apply_theme_to_config(config_path: &Path, theme: &ResolvedTheme) -> Result<String, String> {
    let content = fs::read_to_string(config_path).map_err(|e| format!("Config file not found: {} - {} (os error {})", config_path.display(), e, e.raw_os_error().unwrap_or(0)))?;

    let (clients, bars) = parse_config_for_themes(&content);
    let lines: Vec<String> = content.split('\n').map(|s| s.to_string()).collect();
    let mut new_lines = lines.clone();

    for pc in &clients {
        if let Some(theme_colors) = theme.clients.get(&pc.typ) {
            let mut new_colors = pc.colors.clone();
            for i in 0..theme_colors.len().min(4) {
                if !theme_colors[i].is_empty() {
                    new_colors[i] = theme_colors[i].clone();
                }
            }
            let new_line = format!("{}client.{} {}", pc.indent, pc.typ, new_colors.join(" "));
            new_lines[pc.line_idx] = new_line;
        }
    }

    let existing_types: HashSet<String> = clients.iter().map(|c| c.typ.clone()).collect();
    let order = ["focused","focused_inactive","unfocused","urgent"];
    let mut added = Vec::new();
    for typ in order.iter() {
        if let Some(theme_colors) = theme.clients.get(*typ) {
            if !existing_types.contains(*typ) {
                if theme_colors.len() >= 4 && theme_colors.iter().all(|c| !c.is_empty()) {
                    added.push(format!("client.{} {}", typ, theme_colors.join(" ")));
                }
            }
        }
    }

    let mut bars_sorted = bars.clone();
    bars_sorted.sort_by(|a,b| b.start_idx.cmp(&a.start_idx));

    for bar in bars_sorted {
        if let (Some(_cs), Some(ce)) = (bar.colors_start, bar.colors_end) {
            let mut to_insert: Vec<String> = Vec::new();
            let bar_order = ["separator","background","statusline","focused_workspace","active_workspace","inactive_workspace","urgent_workspace"];
            for typ in bar_order.iter() {
                if let Some(theme_cols) = theme.bar.get(*typ) {
                    let exists = if ["background","statusline","separator"].contains(typ) {
                        bar.singles.iter().any(|s| s.typ == *typ)
                    } else {
                        bar.workspaces.iter().any(|w| w.typ == *typ)
                    };
                    if exists {
                        if ["background","statusline","separator"].contains(typ) {
                            if let Some(ex) = bar.singles.iter().find(|s| s.typ == *typ) {
                                if let Some(hex) = theme_cols.get(0) {
                                    if !hex.is_empty() {
                                        let new_line = format!("{}{} {}", ex.indent, typ, hex);
                                        new_lines[ex.line_idx] = new_line;
                                    }
                                }
                            }
                        } else {
                            if let Some(ex) = bar.workspaces.iter().find(|w| w.typ == *typ) {
                                let mut new_cols = ex.colors.clone();
                                while new_cols.len() < 3 {
                                    new_cols.push("".to_string());
                                }
                                let orig_third = if ex.colors.len() >= 3 { ex.colors[2].clone() } else { "".to_string() };
                                for i in 0..theme_cols.len().min(3) {
                                    if !theme_cols[i].is_empty() {
                                        new_cols[i] = theme_cols[i].clone();
                                    }
                                }
                                if ex.colors.len() >= 4 {
                                    if new_cols.len() >= 4 {
                                        new_cols[3] = orig_third;
                                    } else {
                                        new_cols.push(orig_third);
                                    }
                                }
                                let new_line = if new_cols.len() >= 4 {
                                    format!("{}{} {}", ex.indent, typ, new_cols.join(" "))
                                } else {
                                    format!("{}{} {} ", ex.indent, typ, new_cols[..3].join(" "))
                                };
                                new_lines[ex.line_idx] = new_line;
                            }
                        }
                    } else {
                        let indent = bar.inner_indent.clone().unwrap_or_else(|| "    ".to_string());
                        if ["background","statusline","separator"].contains(typ) {
                            if let Some(hex) = theme_cols.get(0) {
                                if !hex.is_empty() {
                                    to_insert.push(format!("{}{} {}", indent, typ, hex));
                                }
                            }
                        } else {
                            if theme_cols.len() >= 3 && theme_cols.iter().take(3).all(|c| !c.is_empty()) {
                                to_insert.push(format!("{}{} {} ", indent, typ, theme_cols[0..3].join(" ")));
                            }
                        }
                    }
                }
            }
            for entry in to_insert.iter().rev() {
                new_lines.insert(ce, entry.clone());
            }
        } else {
            let colors_indent = "  ".to_string();
            let inner_indent = "    ".to_string();
            let mut block: Vec<String> = Vec::new();
            block.push(format!("{}colors {{", colors_indent));
            let bar_order = ["separator","background","statusline","focused_workspace","active_workspace","inactive_workspace","urgent_workspace"];
            for typ in bar_order.iter() {
                if let Some(cols) = theme.bar.get(*typ) {
                    if ["background","statusline","separator"].contains(typ) {
                        if let Some(hex) = cols.get(0) {
                            if !hex.is_empty() {
                                block.push(format!("{}{} {}", inner_indent, typ, hex));
                            }
                        }
                    } else {
                        if cols.len() >= 3 && cols.iter().take(3).all(|c| !c.is_empty()) {
                            block.push(format!("{}{} {} ", inner_indent, typ, cols[0..3].join(" ")));
                        }
                    }
                }
            }
            block.push(format!("{}}}", colors_indent));
            let insert_pos = bar.end_idx;
            for entry in block.iter().rev() {
                new_lines.insert(insert_pos, entry.clone());
            }
        }
    }

    let mut final_content = new_lines.join("\n");
    if !added.is_empty() {
        if !final_content.ends_with('\n') && !final_content.is_empty() {
            final_content.push('\n');
        }
        for ac in added {
            final_content.push_str(&ac);
            final_content.push('\n');
        }
    } else {
        if content.ends_with('\n') && !final_content.ends_with('\n') {
            final_content.push('\n');
        }
    }

    Ok(final_content)
}

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut config_path: Option<String> = None;
    let mut output_path: Option<String> = None;
    let mut to_theme_path: Option<String> = None;
    let mut theme_arg: Option<String> = None;
    let mut list_all = false;
    let mut reload = false;
    let mut save = false;
    let mut help = false;
    let mut version = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                help = true;
                i += 1;
            }
            "-V" | "--version" => {
                version = true;
                i += 1;
            }
            "-l" | "--list-all" => {
                list_all = true;
                i += 1;
            }
            "-r" | "--reload" => {
                reload = true;
                i += 1;
            }
            "-s" | "--save" => {
                save = true;
                i += 1;
            }
            "-c" | "--config" => {
                if i+1 < args.len() {
                    config_path = Some(args[i+1].clone());
                    i += 2;
                } else {
                    eprintln!("error: option {} requires an argument", arg);
                    process::exit(1);
                }
            }
            "-o" | "--output" => {
                if i+1 < args.len() {
                    output_path = Some(args[i+1].clone());
                    i += 2;
                } else {
                    eprintln!("error: option {} requires an argument", arg);
                    process::exit(1);
                }
            }
            "-t" | "--to-theme" => {
                if i+1 < args.len() && !args[i+1].starts_with('-') {
                    to_theme_path = Some(args[i+1].clone());
                    i += 2;
                } else {
                    to_theme_path = Some("".to_string());
                    i += 1;
                }
            }
            _ => {
                if arg.starts_with('-') {
                    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", arg);
                    eprintln!();
                    print_help();
                    process::exit(1);
                } else {
                    if theme_arg.is_none() {
                        theme_arg = Some(arg.clone());
                    }
                    i += 1;
                }
            }
        }
    }

    if help {
        print_help();
        return;
    }
    if version {
        print_version();
        return;
    }
    if list_all {
        println!();
        println!("Available themes:");
        println!();
        for t in builtin_themes() {
            println!("  {:<18} - {}", t.name, t.description);
        }
        println!();
        return;
    }

    let is_to_theme = to_theme_path.is_some();

    if is_to_theme {
        let tpath_str = to_theme_path.unwrap();
        let tpath = if tpath_str.is_empty() {
            if let Some(p) = find_default_config() {
                p
            } else {
                eprintln!("Could not find i3 config");
                process::exit(1);
            }
        } else {
            PathBuf::from(tpath_str)
        };

        if !tpath.exists() {
            let _ = fs::read_to_string(&tpath).unwrap();
        }

        match generate_theme_from_config(&tpath) {
            Ok(yaml) => {
                print!("{}", yaml);
            }
            Err(e) => {
                eprintln!("{}", e);
                process::exit(1);
            }
        }
        return;
    }

    let cfg_path_buf = if let Some(cp) = config_path {
        PathBuf::from(cp)
    } else {
        if let Some(p) = find_default_config() {
            p
        } else {
            eprintln!("Could not find i3 config");
            process::exit(1);
        }
    };

    let theme_name = if let Some(t) = theme_arg {
        t
    } else {
        print_help();
        process::exit(1);
    };

    let resolved_theme: ResolvedTheme = if let Some(builtin) = load_theme_from_builtin(&theme_name) {
        builtin
    } else {
        let theme_file_path = PathBuf::from(&theme_name);
        match parse_theme_file(&theme_file_path) {
            Ok(rt) => rt,
            Err(e) => {
                eprintln!("Could not open theme: {} - {}", theme_name, e);
                eprintln!(" Use `i3-style --list-all` to see the available themes.");
                process::exit(1);
            }
        }
    };

    let out_path_buf: Option<PathBuf> = if save {
        Some(cfg_path_buf.clone())
    } else {
        output_path.map(PathBuf::from)
    };

    if let Some(out_path) = &out_path_buf {
        if !cfg_path_buf.exists() {
            let _ = fs::read_to_string(&cfg_path_buf).unwrap();
        }

        let new_content = match apply_theme_to_config(&cfg_path_buf, &resolved_theme) {
            Ok(c) => c,
            Err(e) => {
                if e.contains("Config file not found") {
                    let _ = fs::read_to_string(&cfg_path_buf).unwrap();
                }
                eprintln!("{}", e);
                process::exit(1);
            }
        };

        let timestamp = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs();
        let backup_dir = PathBuf::from("/tmp/i3-style").join(timestamp.to_string());
        let _ = fs::create_dir_all(&backup_dir);
        let backup_input = backup_dir.join("config-input");
        let backup_output = backup_dir.join("config-output");
        if let Ok(orig) = fs::read_to_string(&cfg_path_buf) {
            let _ = fs::write(&backup_input, orig);
        }
        let _ = fs::write(&backup_output, &new_content);
        eprintln!("saving config at {} to {}", cfg_path_buf.display(), backup_input.display());

        let write_res = fs::write(out_path, &new_content);
        if let Err(e) = write_res {
            eprintln!("Failed to write output: {}", e);
            process::exit(1);
        }

        let cmd_result = process::Command::new("i3")
            .arg("-C")
            .arg("-c")
            .arg(out_path)
            .output();

        match cmd_result {
            Ok(out) => {
                if !out.status.success() {
                    eprintln!("Could not validate config.");
                    eprintln!("Use `i3 -C -c {}` to see validation errors.", cfg_path_buf.display());
                    process::exit(1);
                }
            }
            Err(e) => {
                eprintln!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {} (os error {})", cfg_path_buf.display(), e, e.raw_os_error().unwrap_or(2));
                process::exit(1);
            }
        }

        if reload {
            let _ = process::Command::new("i3-msg").arg("reload").output();
        }
    } else {
        if !cfg_path_buf.exists() {
            let _ = fs::read_to_string(&cfg_path_buf).unwrap();
        }
        let new_content = match apply_theme_to_config(&cfg_path_buf, &resolved_theme) {
            Ok(c) => c,
            Err(e) => {
                if e.contains("Config file not found") {
                    let _ = fs::read_to_string(&cfg_path_buf).unwrap();
                }
                eprintln!("{}", e);
                process::exit(1);
            }
        };
        print!("{}", new_content);
        if reload {
            let _ = process::Command::new("i3-msg").arg("reload").output();
        }
    }
}
